arguments.prompt:
You are implementing features for a Blazor Web App shipment tracker. The project is already scaffolded at `/tmp/sv-725bd31fd2584ac8a4aec0644742f76e/ShipmentTracker/` with Interactive Auto Global mode and Individual authentication.

Project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client project (interactive components go here)

The App.razor uses `InteractiveAuto` render mode globally. Both projects already have auth wiring.

## Your Tasks

### 1. Remove default template pages
Delete these files from `ShipmentTracker.Client/Pages/`:
- Counter.razor
- Weather.razor

Keep Home.razor (we'll replace its content) and Auth.razor and NotFound.razor.

### 2. Create shared models in the Client project

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public DateTime ShippedDate { get; set; }
}
```

### 3. Create the service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create the client-side implementation using HttpClient

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<Shipment>();
        return null;
    }

    public async Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", status);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<Shipment>();
        return null;
    }
}
```

### 5. Register HttpClient and service in Client Program.cs

Edit `ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient<IShipmentService, ShipmentHttpService>(client =>
{
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress);
});

await builder.Build().RunAsync();
```

### 6. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Today.AddDays(3), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes", ShippedDate = DateTime.Today.AddDays(-2) },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.Today.AddDays(1), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet", ShippedDate = DateTime.Today.AddDays(-7) },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.Today.AddDays(10), CustomerEmail = "carol@example.com", Description = "Auto parts - 5 boxes", ShippedDate = DateTime.Today },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.Today.AddDays(-1), CustomerEmail = "dave@example.com", Description = "Textiles - 3 cartons", ShippedDate = DateTime.Today.AddDays(-5) },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Toronto, CA", Status = ShipmentStatus.Delayed, EstimatedDelivery = DateTime.Today.AddDays(5), CustomerEmail = "eve@example.com", Description = "Perishables - refrigerated", ShippedDate = DateTime.Today.AddDays(-3) },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = status;
        }
        return Task.FromResult(shipment);
    }
}
```

### 7. Add API endpoints and register services in server Program.cs

Edit `ShipmentTracker/Program.cs`. After the line `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();`, add:

```csharp
builder.Services.AddSingleton<IShipmentService, ShipmentServerService>();
```

Add the necessary using statements at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
using ShipmentTracker.Client.Models;
```

Before `app.Run();`, add API endpoints:
```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments");

shipments.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).AllowAnonymous();

shipments.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    var shipment = await service.UpdateShipmentStatusAsync(id, status);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();
```

### 8. Replace Home.razor in the Client project

Replace `ShipmentTracker.Client/Pages/Home.razor` with:
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<div class="container mt-4">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipments in real time, anywhere in the world.</p>

    <div class="row mt-4">
        <div class="col-md-6">
