        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.Today.AddDays(1), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet", ShippedDate = DateTime.Today.AddDays(-7) },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.Today.AddDays(10), CustomerEmail = "carol@example.com", Description = "Auto parts - 5 boxes", ShippedDate = DateTime.Today },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.Today.AddDays(-1), CustomerEmail = "dave@example.com", Description = "Textiles - 3 cartons", ShippedDate = DateTime.Today.AddDays(-5) },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Toronto, CA", Status = ShipmentStatus.Delayed, EstimatedDelivery = DateTime.Today.AddDays(5), CustomerEmail = "eve@example.com", Description = "Perishables - refrigerated", ShippedDate = DateTime.Today.AddDays(-3) },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<Shipment?> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
